# swoop 0.16.1. Generated by scripts/tap-formula in beatzball/swoop on every
# release: change it there, not here.
class Swoop < Formula
  desc "Keyboard launcher: fzf finds, libghostty draws, extensions print lines"
  homepage "https://github.com/beatzball/swoop"
  license "MIT"

  depends_on "fzf"

  on_macos do
    on_arm do
      url "https://github.com/beatzball/swoop/releases/download/v0.16.1/swoop-0.16.1-darwin-arm64.tar.gz"
      sha256 "a5bc2d7a065f74fff046125b1c3d0b94550179735485a1037d2a24cb75c4865b"
    end
    on_intel do
      url "https://github.com/beatzball/swoop/releases/download/v0.16.1/swoop-0.16.1-darwin-amd64.tar.gz"
      sha256 "adcd5002772225c06e1c328728f5e870c2ce710bd36f1fb90c4ff13dae91d141"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/beatzball/swoop/releases/download/v0.16.1/swoop-0.16.1-linux-arm64.tar.gz"
      sha256 "b1bbf12b451cd887350f7305d40d2493bf55774d729eff56c97ec243daef10e8"
    end
    on_intel do
      url "https://github.com/beatzball/swoop/releases/download/v0.16.1/swoop-0.16.1-linux-amd64.tar.gz"
      sha256 "367dc94c7f8f222b412c4c729ec04bbd9e8fa5cf2ebe20a483d1dcbc5d4f76cd"
    end
  end

  def install
    # The tarball stays whole under libexec: bin/swoop finds its tools
    # beside itself and the extensions at ../extensions, and the frame
    # needs its resource bundle beside it. Only the commands are linked.
    libexec.install Dir["*"]
    Dir[libexec/"bin/swoop*"].each do |f|
      next if File.basename(f) == "swoop-shell-mac"

      bin.install_symlink f
    end
  end

  # The frame: a panel on alt+shift+space, at login, on a Mac. The
  # clipboard watcher starts itself the first time the launcher runs.
  service do
    run macos: [opt_libexec/"bin/swoop-shell-mac"]
    keep_alive true
    process_type :interactive
    environment_variables PATH: std_service_path_env, SWOOP_LAUNCHER: opt_libexec/"bin/swoop"
    log_path var/"log/swoop.log"
    error_log_path var/"log/swoop.log"
  end

  # Numbered, because the person reading this has just typed brew install
  # and wants to know what to do next: start it, press the key, and the
  # one permission macOS asks for later. Getting Started on the site says
  # the same three things at more length.
  def caveats
    if OS.mac?
      <<~EOS
        1. Start the frame, now and at every login:
             brew services start swoop
        2. Press alt+shift+space. Esc hides it.
        3. The first time you paste a snippet or an emoji, or move a
           window, macOS asks for Accessibility for swoop-shell-mac.
           Turn it on and try again. Nothing else needs a permission.

        Releases are not signed yet, so after each brew upgrade remove
        swoop-shell-mac from System Settings > Privacy & Security >
        Accessibility and add it again.

        The service sees Homebrew's PATH only. If your AI command lives
        elsewhere, name it in full in ~/.config/swoop/ai, for example:
          ~/.local/bin/claude -p

        swoop restart, swoop stop, swoop start and swoop status look after
        the frame. More: https://swoop.sh/docs/getting-started
      EOS
    else
      <<~EOS
        Run swoop in a terminal. There is no frame on Linux yet.
        More: https://swoop.sh/docs/getting-started
      EOS
    end
  end

  test do
    assert_match "hi", pipe_output("#{bin}/swoop-md -w 40", "# hi\n")
    assert_equal "0.16.1", (libexec/"VERSION").read.strip
  end
end
